// TH15 synthetic type aliases (subset of transcribe/th15/touhou-bullets.ecl).
// Source type numbers are effect ids, not target appearances.
const TH15_STAR_R: int = 608;      // source type16, color6 (GirlD03_at2)
const TH15_BIG_BALL2: int = 656;   // source type19, color3 (GirlD03_at)

// TH15 v1.00b st05.ecl.txt MainSub06 (entry 1575-1596) -> th15_s5_w06
// Dependencies: GirlD03 1028-1052, GirlD03_at 1054-1095, GirlD03_at2 1097-1147.
// Source frame S maps to card frame S+OPENING_BUFFER (plus runtime start offset).
const TIME_LIMIT: int = 2224;
const OPENING_BUFFER: int = 120;

// Source LASER record (EX index 4/5): infinite (a=1), color c=6,
// pair record width r2=16, length n=512. Target constant-width segment:
// 0.9*512 long, width 2*(16/4)=8 (Infinite, w<32).
const LASER_COLOR: int = 6;
const LASER_LEN: fx = 460.8fx;
const LASER_WIDTH: fx = 8fx;

xformdef BULLET_LIFE_30 {
    // Source: EX WAIT 30, then LASER deletes the parent bullet.
    wait(30);
    set_life(1);
}

xformdef AT2_STEP(target_speed: fx, target_angle: angle) {
    // Source STEP type16 a=70 b=1 c=4 (fixed target angle at segment end).
    // Drawn speed is current_speed*(1-t/70); segment end restores speed and angle.
    @70 step_speed(0fx, 70 + 65536 * EASE_LINEAR);
    set_angle(target_angle);
    set_speed(target_speed);
}

async sub delayed_laser(x: fx, y: fx, a: angle, hold: int) {
    // Source LASER infinite: startup30 / expand30 / hold=B / stop30, static origin.
    // Spawned by the firing task, first run is +1 frame, so wait 29.
    wait(29);
    _ = laser(LASER_COLOR, x, y, a, LASER_LEN, LASER_WIDTH, 30, 30 + hold, 30);
}

async sub girl_d03_at(i0: int, i1: int, i2: int, f0: angle, f1: angle) {
    // src1054-1095: etNew(0), etAim(0,3), etSprite(0,19,3), etCount(0,2,1),
    // etAngle(0,0,0), etSpeed(0,3.0,0.2) -> 2-way fixed ring, speed 3.
    wait(60);
    var rank: int = global(GVAR_RANK);
    var a: angle = f1;                     // src1069
    var b: int = i1;                       // src1070
    var c: int = i0;                       // src1071 diffI: Easy i0/2, else i0
    if rank == 0 { c = i0 / 2; }
    var w: int = 5;                        // src1083-1089
    if rank == 0 { w = 10; }
    if rank == 3 { w = 4; }
    while c > 0 {
        // src1076-1077 etAngle(%A) + etOn: two opposite bullets.
        var ca: fx = cos(a);
        var sa: fx = sin(a);
        var a2: angle = a + 180deg;
        var ca2: fx = cos(a2);
        var sa2: fx = sin(a2);
        // etDist24 plus ANIM a=1 retreat 4*3 -> net 12px along each own angle.
        var bx1: fx = $self_x + 12fx * ca;
        var by1: fx = $self_y + 12fx * sa;
        var bx2: fx = $self_x + 12fx * ca2;
        var by2: fx = $self_y + 12fx * sa2;
        _ = fire(TH15_BIG_BALL2, 3, bx1, by1, 3fx, a, BULLET_LIFE_30, none);
        _ = fire(TH15_BIG_BALL2, 3, bx2, by2, 3fx, a2, BULLET_LIFE_30, none);
        // LASER enters 30 frames after birth; bullet then travelled 30*3px.
        spawn delayed_laser($self_x + 102fx * ca, $self_y + 102fx * sa, a, b);
        spawn delayed_laser($self_x + 102fx * ca2, $self_y + 102fx * sa2, a2, b);
        a = a - f0;                        // src1078-1079
        b = b - i2;
        if rank == 0 {                     // src1080-1083 Easy extra step
            a = a - f0;
            b = b - i2;
        }
        wait(w);
        c = c - 1;
    }
}

async sub girl_d03_at2() {
    // src1097-1147: etNew(1), etAim(1,1), etSprite(1,16,6), etCount(1,1,1),
    // etAngle(1,90deg,20deg), etSpeed(1,2.0,1.0) -> 1-way random spray.
    wait(70);
    var rank: int = global(GVAR_RANK);
    var n: int = 60;                       // src1109 diffI 60/200/300/300
    if rank == 1 { n = 200; }
    if rank >= 2 { n = 300; }
    var w: int = 3;                        // src1134-1142
    if rank == 0 { w = 9; }
    if rank >= 2 { w = 2; }
    while n > 0 {
        // src1112-1119: STEP target speed s (sampled first).
        var r1: int = rand(65536);
        var u1: fx = (r1 - 32768) as fx / 65536 + 0.5fx;
        var v1: fx = 1fx + u1;
        if rank >= 2 { v1 = 2fx + u1; }
        // src1121: target angle 90deg + RANDF2*10deg.
        var r2: int = rand(65536);
        var roff: int = ((r2 - 32768) * 1820) / 32768;
        var ra: angle = 90deg + (roff as angle);
        // src1122-1131: initial speed (sampled after the angle).
        var r3: int = rand(65536);
        var u2: fx = (r3 - 32768) as fx / 65536 + 0.5fx;
        var v2: fx = 1fx + 4fx * u2;
        if rank >= 2 { v2 = 2fx + 3fx * u2; }
        // src1132-1133: etAngle(RANDRAD) + etOn.
        var ang: angle = (rand(65536)) as angle;
        var ca: fx = cos(ang);
        var sa: fx = sin(ang);
        // etDist24 plus ANIM a=1 retreat 4*v2 -> net (24-4*v2)px.
        var d: fx = 24fx - 4fx * v2;
        _ = fire(TH15_STAR_R, 6, $self_x + d * ca, $self_y + d * sa, v2, ang,
                 AT2_STEP(v1, ra), none);
        wait(w);
        n = n - 1;
    }
}

async sub girl_d03(i0: int, i1: int, i2: int, f0: angle, f1: angle) {
    // src1028-1052. Creation variant is enmCreateM (child mirror=1); under the
    // shared rule mirror is applied at movement write points only, so the 90deg
    // move and the source-authored firing angles are unchanged here.
    set_invuln(65535);
    set_hurtbox(16fx);                     // src500 (32,32) -> 0.5*first
    set_hitbox(12fx);                      // src501 (24,24) -> 0.5*first
    move_vel(0, 90deg, 4.7fx, EASE_LINEAR);      // src1039
    move_speed(60, 0fx, EASE_QUAD_IN);           // src1040 mode1 = t^2
    spawn girl_d03_at(i0, i1, i2, f0, f1);       // src1041
    spawn girl_d03_at2();                        // src1042
    wait(600);                                   // src1043
    move_speed(80, 1fx, EASE_QUAD_IN);           // src1044 mode1
    wait(60);                                    // src1045
    loop { wait(1000); }                         // src1047-1050
}

async sub pattern() {
    wait(OPENING_BUFFER);
    wait(100);                             // src1577
    var r1: int = rand(65536);
    var u1: fx = (r1 - 32768) as fx / 32768;
    _ = spawn_enemy(64fx + u1 * 32fx, -48fx, 7000, 0, 0, 0,
                    girl_d03(26, 140, 5, 8deg, 135deg));   // src1578-1583
    wait(380);                             // src1584
    var r2: int = rand(65536);
    var u2: fx = (r2 - 32768) as fx / 32768;
    _ = spawn_enemy(-64fx + u2 * 32fx, -48fx, 6000, 0, 0, 0,
                    girl_d03(26, 140, 5, -8deg, 45deg));   // src1585-1587
    wait(380);                             // src1588
    _ = spawn_enemy(0fx, -48fx, 8000, 0, 0, 0,
                    girl_d03(72, 30, 0, 222.5deg, 45deg)); // src1589-1593
    wait(20);                              // src1594
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
